CREATE TABLE ticket_connectors(tenant_id integer NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, provider text NOT NULL CHECK(provider IN ('zendesk','servicenow')), hostname text NOT NULL, credential text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,provider));
CREATE TABLE external_tickets(tenant_id integer NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, provider text NOT NULL, ticket_id integer NOT NULL REFERENCES tickets(id) ON DELETE CASCADE, external_id text NOT NULL, synced_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,provider,ticket_id), FOREIGN KEY(tenant_id,provider) REFERENCES ticket_connectors(tenant_id,provider) ON DELETE CASCADE);
